-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_DOMICILIOS_VERSION` BEFORE UPDATE ON `FB_DOMICILIOS` FOR EACH ROW
BEGIN
IF NOT (BINARY OLD.`ID_DOMICILIO` <=> BINARY NEW.`ID_DOMICILIO`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_IDENTIDAD_INMUTABLE'; END IF;
IF NEW.ID_CONSULTA < OLD.ID_CONSULTA OR EXISTS (SELECT 1 FROM FB_CIU_CONSULTAS_WEB WHERE ID_PERSONA=NEW.ID_PERSONA AND ID_CONSULTA>NEW.ID_CONSULTA) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ORIGEN_ANTIGUO'; END IF;
IF NOT (BINARY OLD.`ID_DOMICILIO` <=> BINARY NEW.`ID_DOMICILIO`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) OR NOT (BINARY OLD.`ID_PERSONA_CP` <=> BINARY NEW.`ID_PERSONA_CP`) OR NOT (BINARY OLD.`ID_DOMICILIO_CP` <=> BINARY NEW.`ID_DOMICILIO_CP`) OR NOT (BINARY OLD.`ID_CONSULTA` <=> BINARY NEW.`ID_CONSULTA`) OR NOT (BINARY OLD.`CALLE` <=> BINARY NEW.`CALLE`) OR NOT (BINARY OLD.`NUMERO` <=> BINARY NEW.`NUMERO`) OR NOT (BINARY OLD.`BARRIO` <=> BINARY NEW.`BARRIO`) OR NOT (BINARY OLD.`LOCALIDAD` <=> BINARY NEW.`LOCALIDAD`) OR NOT (BINARY OLD.`DEPARTAMENTO` <=> BINARY NEW.`DEPARTAMENTO`) OR NOT (BINARY OLD.`CODIGO_POSTAL` <=> BINARY NEW.`CODIGO_POSTAL`) OR NOT (BINARY OLD.`PH` <=> BINARY NEW.`PH`) OR NOT (BINARY OLD.`BLOCK` <=> BINARY NEW.`BLOCK`) OR NOT (BINARY OLD.`DEPTO` <=> BINARY NEW.`DEPTO`) OR NOT (BINARY OLD.`PUERTA` <=> BINARY NEW.`PUERTA`) OR NOT (BINARY OLD.`DOMICILIO_COMPLETO` <=> BINARY NEW.`DOMICILIO_COMPLETO`) OR NOT (BINARY OLD.`REFERENCIA` <=> BINARY NEW.`REFERENCIA`) OR NOT (BINARY OLD.`SECTOR` <=> BINARY NEW.`SECTOR`) OR NOT (BINARY OLD.`MANZANA` <=> BINARY NEW.`MANZANA`) OR NOT (BINARY OLD.`LOTE` <=> BINARY NEW.`LOTE`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) OR NOT (BINARY OLD.`VERIFICACION_CP_JSON` <=> BINARY NEW.`VERIFICACION_CP_JSON`) THEN
 IF NEW.USUARIO_MODIFICADOR_ID IS NULL OR CHAR_LENGTH(TRIM(NEW.USUARIO_MODIFICADOR_ID))=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ACTOR_REQUERIDO'; END IF;
 SET NEW.VERSION=OLD.VERSION+1; SET NEW.FECHA_MODIFICACION=UTC_TIMESTAMP(6);
 ELSE SET NEW.VERSION=OLD.VERSION; SET NEW.FECHA_MODIFICACION=OLD.FECHA_MODIFICACION; SET NEW.USUARIO_MODIFICADOR_ID=OLD.USUARIO_MODIFICADOR_ID; END IF;
END$$
DELIMITER ;
